/* Quais status da Base são cancelamento — perguntando a ela, não cravando id.

   Os ids mudam de conta para conta e ninguém lembra de vir aqui no dia em
   que mudarem. E há mais de um: no painel aparecem "Cancelado", "Cancelado
   com Devolução" e "Cancelado com NF". Os dois primeiros vão para a lista
   Canceladas; o terceiro tem fila própria porque envolve estorno de nota. */
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Não consegui ler os status da Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const lista = Array.isArray(r.statuses) ? r.statuses
            : Object.entries(r.statuses || {}).map(([id, v]) => ({ id, name: (v && v.name) || String(v) }));

const comNF = [], simples = [];
lista.forEach(s => {
  const nome = String(s.name || '');
  if (!/cancel/i.test(nome)) return;
  /* "com NF" e "nota fiscal" são a mesma coisa escrita de dois jeitos; a
     leitura é pelo texto porque é o texto que a operação lê no painel. */
  if (/\bnf\b|nota\s*fiscal/i.test(nome)) comNF.push({ id: String(s.id), nome });
  else simples.push({ id: String(s.id), nome });
});

if (!comNF.length && !simples.length) {
  throw new Error('Nenhum status com "cancel" no nome. Status existentes: '
    + lista.map(s => s.id + '=' + s.name).join(' | '));
}
console.log('cancelamento simples: ' + (simples.map(s => s.nome).join(', ') || '—')
  + ' | com NF: ' + (comNF.map(s => s.nome).join(', ') || '—'));

return [{ json: { comNF, simples } }];

/* Ponto de partida da varredura.

   id_from = 0 varre tudo que a Base ainda entrega. Parece exagero para um
   fluxo de hora em hora, e não é: cancelamento acontece DEPOIS que o pedido
   foi criado. Se a varredura só olhasse os ids novos, o pedido de terça
   cancelado hoje nunca seria visto — ele não é novo, o cancelamento é. Como
   a Base só devolve os últimos 90 dias, "tudo" é uma janela fechada.

   O contador zera aqui, e não no fim: dado estático do n8n sobrevive entre
   execuções, e um contador que não zera vira número inventado no log. */
const est = $getWorkflowStaticData('global');
est.canc = { paginas: 0, lidos: 0, novos: 0, jaTinha: 0, semData: 0 };
return [{ json: { proximoId: 0 } }];

/* Uma página da Base vira registros das duas listas.

   ── Por que o filtro de status é feito aqui, e não na chamada ────────
   O filter_order_status_id da BaseLinker é ignorado em silêncio: devolve
   pedidos de outro status como se tivesse funcionado. Medido em 22/08/2026.
   Filtro que falha calado é pior que filtro nenhum, então a leitura traz
   tudo e a separação acontece neste código.

   ── Por que registro que já existe NUNCA é regravado ─────────────────
   O registro no LiveOps tem vida própria depois de criado: alguém marca
   como concluída, o prazo corre, a tarefa é gerada. Regravar em cima
   devolveria tudo para "a fazer" a cada rodada — a fila do dia seria
   ressuscitada de hora em hora. Por isso a comparação é por CHAVE, e a
   chave é o número do pedido: existe, não toca. */
const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou a leitura de pedidos: ' + (r.error_message || r.error_code || JSON.stringify(r).slice(0, 300)));
}
const pedidos = r.orders || [];
const est = $getWorkflowStaticData('global');
const c = est.canc || (est.canc = { paginas: 0, lidos: 0, novos: 0, jaTinha: 0, semData: 0 });

/* Página vazia = acabou. Devolver zero itens encerra o laço sozinho: sem
   item, nada segue adiante e a repetição para. */
if (!pedidos.length) {
  console.log('── varredura terminada ──');
  console.log(c.paginas + ' página(s) · ' + c.lidos + ' pedido(s) lidos');
  console.log(c.novos + ' cancelamento(s) novo(s) · ' + c.jaTinha + ' já estavam no LiveOps');
  return [];
}

const cfg = $('Quais status são cancelamento').first().json;
const idsNF = new Set(cfg.comNF.map(s => s.id));
const idsSimples = new Set(cfg.simples.map(s => s.id));
const nomePorId = {};
cfg.comNF.concat(cfg.simples).forEach(s => { nomePorId[s.id] = s.nome; });

/* Resposta vazia do Firebase volta como null, e Object.keys(null) explode. */
const obj = v => (v && typeof v === 'object') ? v : {};
/* ?shallow=true devolve só as chaves ({"canc_123": true}), não os registros.
   É tudo que a comparação precisa e evita baixar a base inteira a cada hora. */
const jaExiste = new Set(
  Object.keys(obj($('Canceladas já gravadas').first().json))
    .concat(Object.keys(obj($('Com NF já gravadas').first().json)))
);

/* Nome de canal legível. O order_source vem como "personal", "shop",
   "melibr"… — código de máquina que ninguém reconhece na tela. */
const CANAL = {
  personal: 'WHATSAPP', shop: 'LOJA INTEGRADA', melibr: 'MERCADO LIVRE',
  shopeebr: 'SHOPEE', magalu: 'MAGALU', omnik: 'WHATSAPP'
};

const TZ = 'America/Sao_Paulo';
const partes = ts => {
  const d = new Intl.DateTimeFormat('sv-SE', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(new Date(Number(ts) * 1000));
  const h = new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' })
    .format(new Date(Number(ts) * 1000));
  const [a, m, dia] = d.split('-');
  return { iso: d, ano: Number(a), br: dia + '/' + m + '/' + a + ', ' + h };
};

const carimbo = new Date().toLocaleString('pt-BR', { timeZone: TZ });
const canceladas = {}, canceladasNF = {};
let maior = 0, novosAqui = 0;

pedidos.forEach(p => {
  const id = Number(p.order_id) || 0;
  if (id > maior) maior = id;
  c.lidos++;

  const idStatus = String(p.order_status_id);
  const ehNF = idsNF.has(idStatus);
  if (!ehNF && !idsSimples.has(idStatus)) return;

  const quando = Number(p.date_add || p.date_confirmed || 0);
  if (!quando) { c.semData++; return; }
  const q = partes(quando);

  const numero = String(p.order_id);
  const chave = (ehNF ? 'cancnf_' : 'canc_') + numero;
  if (jaExiste.has(chave)) { c.jaTinha++; return; }

  const registro = {
    id: chave,
    cliente: p.delivery_fullname || p.invoice_fullname || p.user_login || '',
    cpf: String(p.invoice_nip || '').replace(/\D/g, ''),
    telefone: String(p.phone || '').replace(/\D/g, ''),
    plataforma: CANAL[String(p.order_source || '')] || String(p.order_source || '').toUpperCase(),
    pedidoBase: numero,
    dataPedido: q.iso,
    statusBase: nomePorId[idStatus] || ('status ' + idStatus),
    produtos: ehNF ? (p.products || []).map(function (x) {
      return { sku: String(x.sku || ''), nome: String(x.name || ''), qtd: Number(x.quantity) || 1 };
    }) : undefined,
    status: 'aberta',
    criadoEm: q.br,
    criadoPor: 'Base',
    ordemManual: Number(quando) * 1000,
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };
  (ehNF ? canceladasNF : canceladas)[chave] = registro;
  jaExiste.add(chave);
  novosAqui++; c.novos++;
});

c.paginas++;
console.log('página ' + c.paginas + ': ' + pedidos.length + ' pedido(s) · '
  + novosAqui + ' cancelamento(s) novo(s) · próximo id ' + (maior + 1));

/* Um item só, e três caminhos saem dele: as duas gravações e a pausa que
   devolve o laço para a página seguinte. O nó Code tem uma saída só. */
return [{ json: { canceladas, canceladasNF, proximoId: maior + 1 } }];
